sources.text:
/**
 * 负责狼聊、狼刀及自爆的校验贡献。输入为可信演员权限、阶段／窗口和提交工具，输出为原首个规则拒绝或预检通过。
 * 原 pass 检查之后才读取公开的只读狼刀候选；校验不消费库存、不制造狼刀或提交效果。
 */
import { canRoleSelfDestruct } from "../self_destruct_capability";
import { bindWolfKnifeTargetQuery } from "./ports";
import {
  weddingMember,
  weddingSetup,
  ghostBrideReady,
  canSubmitWeddingTool,
} from "../ghost_bride/authority";
import { RuleError } from "@ai-werewolf-arena/game-contract";
/** 文件说明：狼人工具校验规则。 */
import { ActionWindow, Phase } from "../../../../core/domain/model";
import { ToolRuleMap } from "../../validation/contracts";
import { wolfTeamPermissions } from "../wolf_team";

/** 狼人工具校验规则集合。 */
export const WOLF_VALIDATION_RULES: ToolRuleMap = {
  speak_to_wolves: ({ world, role, roleCatalog, phase }) => {
    if (!wolfTeamPermissions(role, roleCatalog, world).canChat) {
      return { code: RuleError.WolfChatPermission };
    }
    if (phase !== Phase.Night) return { code: RuleError.WolfChatPhase };
    return null;
  },
  kill_vote: ({ world, actorId, day, ghostBrideScope, role, roleCatalog, toolCall, phase }) => {
    if (weddingSetup(world))
      return canSubmitWeddingTool(world, actorId, phase, day ?? 0, ghostBrideScope, toolCall)
        ? null
        : { code: RuleError.GhostBrideUnavailable };
    if (!wolfTeamPermissions(role, roleCatalog, world).canVoteForKill) {
      return { code: RuleError.WolfKillPermission };
    }
    if (phase !== Phase.Night) return { code: RuleError.WolfKillPhase };
    if (toolCall.name !== "kill_vote") {
      return { code: RuleError.ToolMismatch };
    }
    if (toolCall.args.abstain) {
      return null;
    }
    if (
      toolCall.args.target_id === null ||
      !bindWolfKnifeTargetQuery(world).allows(toolCall.args.target_id)
    ) {
      return { code: RuleError.KillTarget };
    }
    return null;
  },
  self_destruct: ({
    world,
    role,
    roleCatalog,
    phase,
    actionWindow,
    allowSelfDestruct,
    toolCall,
  }) => {
    if (weddingSetup(world) && (!ghostBrideReady(world) || weddingMember(world, role)))
      return { code: RuleError.WolfBlastOnly };
    if (!canRoleSelfDestruct(role, roleCatalog)) {
      return { code: RuleError.WolfBlastOnly };
    }
    if (phase !== Phase.Day && phase !== Phase.Voting) {
      return { code: RuleError.BlastPhase };
    }
    if (actionWindow === undefined || !Object.values(ActionWindow).includes(actionWindow)) {
      return { code: RuleError.BlastWindow };
    }
    if (phase !== (actionWindow === ActionWindow.OnPreVote ? Phase.Voting : Phase.Day))
      return { code: RuleError.BlastPhase };
    if (!allowSelfDestruct) {
      return { code: RuleError.BlastDisabled };
    }
    if (toolCall.name !== "self_destruct" || toolCall.args.confirm !== true) {
      return { code: RuleError.BlastConfirm };
    }
    return null;
  },
};

/**
 * 负责共享普通狼贡献的完整装配，供普通狼人及派生角色复用原资料、狼聊、狼刀、自爆与 mock。
 * 输入是原狼工具、阶段、校验、修复与提示定义；输出是唯一普通狼三贡献对象及原数组、handler 和回调引用。
 * 保留 metadata、runtime、presentation 的创建顺序及普通狼默认展示；实际 Catalog 注册仍由 wolf/profile 入口引用。
 * 派生角色在原字段读取／展开点读取这一可写对象，运行时替换 runtime 或 getter 仍按原时点生效，不提前缓存。
 * 本模块不建立通用角色基类，不推进阶段或付款，不授予生命、库存和租约写权；展示身份不构成行动许可。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { Camp, Role } from "../../../../core/domain/model";
import { NativeRoleContributions } from "../contracts";
import { WOLF_LLM_REPAIR_PACK } from "./llm_repair";
import { WOLF_NIGHT_STAGES } from "./night_stages";
import { WOLF_TOOL_SPECS, WOLF_STAGE_DIRECTIVES } from "./tool_specs";
import { WOLF_VALIDATION_RULES } from "./validation_rules";
import { isMistRavenBoard, mistKnifeTargets } from "../mist_raven/ports";

/** 同一对象保留原四字段资料、完整运行贡献和最后创建的普通狼人展示；字段仍可写，不预取 runtime。 */
export const ORDINARY_WOLF_CONTRIBUTIONS: NativeRoleContributions = {
  metadata: {
    role: Role.Wolf,
    camp: Camp.Wolf,
    label: roleName("wolf"),
    skillBrief: text("zh-CN", "role.wolf.brief"),
  },
  runtime: {
    canSelfDestruct: true,
    wolfTeam: { recognizedByPack: true, recognizes: "pack", canChat: true, canVoteForKill: true },
    toolSpecs: WOLF_TOOL_SPECS,
    stageDirectives: WOLF_STAGE_DIRECTIVES,
    validationRules: WOLF_VALIDATION_RULES,
    nightStages: WOLF_NIGHT_STAGES,
    llmRepair: WOLF_LLM_REPAIR_PACK,
    baselineAction: (
      _roleComp,
      request,
      _pickAliveNotSelf,
      pickAliveByCamp,
      locale = "zh-CN",
      world,
    ) => {
      if (request.allowedTools.includes("speak_to_wolves")) {
        return {
          name: "speak_to_wolves",
          args: {
            text: text(locale, "fallback.wolf_chat"),
            end_chat: false,
          },
        };
      }
      if (request.allowedTools.includes("kill_vote")) {
        const circle = world && isMistRavenBoard(world) ? mistKnifeTargets(world) : null;
        if (circle !== null) {
          const target = circle[0] ?? null;
          return { name: "kill_vote", args: { target_id: target, abstain: target === null } };
        }
        const target = pickAliveByCamp("good");
        if (target !== null) {
          return { name: "kill_vote", args: { target_id: target, abstain: false } };
        }
        return { name: "kill_vote", args: { target_id: null, abstain: true } };
      }
      if (request.allowedTools.includes("self_destruct")) {
        // 自爆属于高风险动作：fallback 不应在“可选中断窗口”默认触发。
        return null;
      }
      return null;
    },
  },
  presentation: nativeRolePresentation("wolf"),
};

/**
 * 负责公开共享普通狼贡献与五个实际能力常量，供派生角色通过具名公共边界复用。
 * 输入为本族唯一装配对象与原工具／阶段／校验／提示／修复常量；输出是原 same-binding 引用，不复制数组或包装方法。
 * 普通狼贡献对象的 metadata／runtime 仍在原调用点晚读，直接能力常量仍保持原独立变量语义。
 * 本端口不建立角色注册、生命周期或权限屏障；与狼刀查询端口分开，避免夜间 handler 反向导入自身装配。
 */
export { ORDINARY_WOLF_CONTRIBUTIONS } from "./ability-assembly";
export { WOLF_NIGHT_STAGES } from "./night_stages";
export { WOLF_TOOL_SPECS, WOLF_STAGE_DIRECTIVES } from "./tool_specs";
export { WOLF_VALIDATION_RULES } from "./validation_rules";
export { WOLF_LLM_REPAIR_PACK } from "./llm_repair";

/**
 * Owns ordinary wolf knife target composition through four feature public queries.
 * Inputs are current target IDs, circle/role allowances and alive membership;
 * output is the original allowed-target boolean. Mist precedes Noble, alive,
 * Evil Knight and Nightmare checks with the same short-circuit failure order.
 * Binding reads no World state; query consumers receive no Role, life, stock,
 * random source, writable World or effect-commit capability.
 */
import type { EntityId } from "../../../../core/domain/identity";
import type { World } from "../../../../core/domain/world";
import { bindMistKnifeTargetQuery, type MistKnifeTargetQuery } from "../mist_raven/ports";
import { bindNobleKnifeTargetQuery, type NobleKnifeTargetQuery } from "../noble_secret_body/ports";
import {
  bindEvilKnightKnifeTargetQuery,
  type EvilKnightKnifeTargetQuery,
} from "../evil_knight/ports";
import {
  bindNightmareKnifeTargetQuery,
  type NightmareKnifeTargetQuery,
} from "../nightmare_shadow/ports";

export interface WolfKnifeRosterQuery {
  aliveIds(): readonly EntityId[];
}
export interface WolfKnifeTargetQuery {
  allows(targetId: EntityId): boolean;
}

/** Concrete declaration order, not an extensible rule graph or role callback registry. */
export function createWolfKnifeTargetQuery(
  roster: WolfKnifeRosterQuery,
  mist: MistKnifeTargetQuery,
  noble: NobleKnifeTargetQuery,
  evilKnight: EvilKnightKnifeTargetQuery,
  nightmare: NightmareKnifeTargetQuery,
): WolfKnifeTargetQuery {
  return Object.freeze({
    allows(targetId: EntityId) {
      const circle = mist.targets();
      return (
        (circle === null || circle.includes(targetId)) &&
        noble.allows(targetId) &&
        roster.aliveIds().includes(targetId) &&
        evilKnight.allows(targetId) &&
        nightmare.allows(targetId)
      );
    },
  });
}

/** Capture the argument reference only; defer all queries until allows is called. */
export function bindWolfKnifeTargetQuery(world: World): WolfKnifeTargetQuery {
  return createWolfKnifeTargetQuery(
    { aliveIds: () => world.getAliveEntityIds() },
    bindMistKnifeTargetQuery(world),
    bindNobleKnifeTargetQuery(world),
    bindEvilKnightKnifeTargetQuery(world),
    bindNightmareKnifeTargetQuery(world),
  );
}

/**
 * 提供鬼魂新娘具体夜间生命周期、死亡波发布、玩家知识及请求预检的公开入口。
 * 输入保留原 World、捕获／关闭引用与所属事件；输出为原单元、已告知数据和请求查询结果。
 * 死亡关系在原初始／追加波处扩张并发布，开启在原夜间阶段，晚移交先于 pipeline 清理；close／abort 保持经理与 pipeline 顺序。
 * 单元独自拥有清理移交，准备与已付款关系各归原权威；原当前性和读写权限检查不变。
 * 具名出口不增加回合、库存或作用域权限，不把玩家关系知识当成提交许可。
 */
export { WeddingNightUnit, weddingNightTerminal } from "./night-lifecycle";

/** 原引擎查询保持同一权威函数绑定与参数。 */
export {
  weddingSetup,
  ghostBrideReady,
  hasActiveGhostBride,
  hasGhostBrideNightCommit,
  weddingAssignment,
  weddingKnifeCurrent,
} from "./authority";

export { weddingBrideState } from "./authority";

export { ghostBrideRequestScope } from "./authority";

/** 原地关系扩张及逐边事实归机制；日期／阶段／事件仍按原时点晚读，不提交实际死亡。 */
export { WeddingDeathWavePublication } from "./death-wave-publication";

/** 开局组合使用同一准备类绑定；具体窗口仍拥有选择校验、提交与失败关闭。 */
export { GhostBrideSetupWindow } from "./setup";

controls.text:
/**
 * 负责 狼美人 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { BEAUTY_DEATH_LINK_POLICIES } from "../../../../core/domain/board";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { text, roleName } from "@ai-werewolf-arena/game-text";
import { Role, Camp, Phase } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
import { getWolfBeautyState, setWolfBeautyState } from "./state";
import { ORDINARY_WOLF_CONTRIBUTIONS } from "../wolf/ability-ports";
import { WOLF_VALIDATION_RULES } from "../wolf/ability-ports";
import { isAliveTarget } from "../../validation/contracts";
import { numberOrNull } from "../../llm/helpers";
import { WOLF_BEAUTY_CHARM_STAGE } from "./night_stages";
import { wolfBeautyDeathHook } from "./death_hook";
import { animalBeautyCharmAllowed, isAnimalDreamBoard } from "../animal_dream/authority";
import { animalBeautyKnowledge } from "../animal_dream/facts";
import { COMPONENT } from "../../../../core/domain/components/names";

const parameters = z.strictObject({
  deathLinkPolicy: z.enum(BEAUTY_DEATH_LINK_POLICIES).default("awa_exile_poison_v1"),
});

export const WOLF_BEAUTY_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.metadata,
    role: Role.WolfBeauty,
    label: roleName("wolf_beauty"),
    skillBrief: text("zh-CN", "role.wolf_beauty.brief"),
  },
  runtime: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.runtime,
    canSelfDestruct: false,
    init: (role, ctx) => {
      setWolfBeautyState(role, {
        targetId: null,
        lastActedDay: null,
        history: [],
        ...(ctx.boardConfig?.wolfBeauty?.deathLinkPolicy &&
        ctx.boardConfig.wolfBeauty.deathLinkPolicy !== "awa_exile_poison_v1"
          ? { deathLinkPolicy: ctx.boardConfig.wolfBeauty.deathLinkPolicy }
          : {}),
      });
    },
    configuration: {
      schema: parameters,
      defaults: { deathLinkPolicy: "awa_exile_poison_v1" },
      apply: (config, value) => ({ ...config, wolfBeauty: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.wolfBeauty ?? {}),
    },
    nightStages: [...ORDINARY_WOLF_CONTRIBUTIONS.runtime.nightStages!, WOLF_BEAUTY_CHARM_STAGE],
    deathHook: wolfBeautyDeathHook,
    toolSpecs: [
      ...ORDINARY_WOLF_CONTRIBUTIONS.runtime.toolSpecs!.filter((spec) => spec.name !== "self_destruct"),
      {
        name: "charm",
        parameters: {
          type: "object",
          properties: { target_id: { type: ["number", "null"] } },
          required: ["target_id"],
          additionalProperties: false,
        },
        argHint: 'charm args: {"target_id":number|null}',
        userPromptHintKey: "action.charm.hint",
      },
    ],
    validationRules: {
      ...WOLF_VALIDATION_RULES,
      kill_vote: (ctx) => {
        const inherited = WOLF_VALIDATION_RULES.kill_vote!(ctx);
        if (inherited) return inherited;
        return ctx.toolCall.name === "kill_vote" &&
          !ctx.toolCall.args.abstain &&
          ctx.toolCall.args.target_id === ctx.actorId
          ? { code: RuleError.BeautySelfKnife }
          : null;
      },
      charm: ({ world, actorId, role, phase, day, toolCall }) => {
        const state = getWolfBeautyState(role);
        if (
          role.role !== Role.WolfBeauty ||
          role.camp !== Camp.Wolf ||
          !state ||
          !animalBeautyCharmAllowed(world, day ?? 0) ||
          state.lastActedDay === day
        )
          return { code: RuleError.CharmUnavailable };
        if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
        if (toolCall.name !== "charm") return { code: RuleError.ToolMismatch };
        if (toolCall.args.target_id === null) return null;
        if (toolCall.args.target_id === actorId || !isAliveTarget(world, toolCall.args.target_id))
          return { code: RuleError.CharmTarget };
        const previous = state.history.at(-1);
        return previous?.day === (day ?? 1) - 1 && previous.targetId === toolCall.args.target_id
          ? { code: RuleError.CharmRepeat }
          : null;
      },
    },
    llmRepair: {
      coerce: {
        ...ORDINARY_WOLF_CONTRIBUTIONS.runtime.llmRepair?.coerce,
        charm: (args) => {
          if (args.target_id === null) return { target_id: null };
          const target = numberOrNull(args.target_id);
          return target === null ? null : { target_id: target };
        },
      },
    },
    baselineAction: (role, request, pick, byCamp, locale) => {
      if (request.allowedTools.includes("charm")) {
        const target = pick(),
          previous = getWolfBeautyState(role)?.history.at(-1);
        return {
          name: "charm",
          args: {
            target_id:
              previous?.day === request.context.day - 1 && previous.targetId === target
                ? null
                : target,
          },
        };
      }
      return ORDINARY_WOLF_CONTRIBUTIONS.runtime.baselineAction!(role, request, pick, byCamp, locale);
    },
  },
  presentation: nativeRolePresentation("wolf_beauty"),
};

/**
 * 负责 野孩子 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { Camp, Role, WinCondition } from "../../../../core/domain";
import type { NativeRoleContributions } from "../contracts";
import { WOLF_NIGHT_STAGES } from "../wolf/ability-ports";
import { WOLF_TOOL_SPECS, WOLF_STAGE_DIRECTIVES } from "../wolf/ability-ports";
import { WOLF_VALIDATION_RULES } from "../wolf/ability-ports";
import { WOLF_LLM_REPAIR_PACK } from "../wolf/ability-ports";
import { ORDINARY_WOLF_CONTRIBUTIONS } from "../wolf/ability-ports";
import {
  WILD_CHILD_POLICY,
  freshWildChildState,
  getWildChildState,
  readWildChildTool,
} from "./state";
import {
  authorizedWildChild,
  projectWildChild,
  wildChildPackActive,
  wildChildPackKnown,
} from "./lifecycle";
const parameters = z.strictObject({
  policy: z.literal(WILD_CHILD_POLICY).default(WILD_CHILD_POLICY),
});
export const WILD_CHILD_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.WildChild,
    camp: Camp.Good,
    goodSide: "villager",
    maxCount: 1,
    supportedWinConditions: [WinCondition.SlaughterCity],
    supportedBoardRoles: [
      Role.WildChild,
      Role.Wolf,
      Role.Villager,
      Role.Seer,
      Role.Witch,
      Role.Hunter,
      Role.Guard,
      Role.Idiot,
    ],
    label: roleName("wild_child"),
    skillBrief: text("zh-CN", "role.wild_child.brief"),
  },
  runtime: {
    canSelfDestruct: false,
    init: (role) => {
      if (!getWildChildState(role)) role.privateState.wildChild = freshWildChildState();
    },
    configuration: {
      schema: parameters,
      defaults: { policy: WILD_CHILD_POLICY },
      apply: (config, value) => ({ ...config, wildChild: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.wildChild ?? {}),
    },
    wolfTeam: (role, world) => ({
      recognizedByPack: wildChildPackKnown(role, world),
      recognizes: wildChildPackKnown(role, world) ? "pack" : "none",
      canChat: wildChildPackActive(role, world),
      canVoteForKill: wildChildPackActive(role, world),
    }),
    nightStages: WOLF_NIGHT_STAGES,
    stageDirectives: WOLF_STAGE_DIRECTIVES,
    toolSpecs: [
      ...WOLF_TOOL_SPECS.filter((spec) => spec.name !== "self_destruct"),
      {
        name: "choose_wild_model",
        parameters: {
          type: "object",
          properties: { target_id: { type: "integer" } },
          required: ["target_id"],
          additionalProperties: false,
        },
        argHint: 'choose_wild_model args: {"target_id":number}',
        userPromptHintKey: "action.choose_wild_model.hint",
      },
    ],
    validationRules: {
      ...WOLF_VALIDATION_RULES,
      choose_wild_model: ({ world, actorId, day, phase, toolCall, wildChildScope }) =>
        !authorizedWildChild(world, actorId, day, phase, wildChildScope)
          ? { code: RuleError.WildChildUnavailable }
          : readWildChildTool(toolCall) &&
              toolCall.name === "choose_wild_model" &&
              toolCall.args.target_id !== actorId &&
              world.getAliveEntityIds().includes(toolCall.args.target_id)
            ? null
            : { code: RuleError.WildChildChoice },
    },
    llmRepair: WOLF_LLM_REPAIR_PACK,
    baselineAction: (role, request, pickAliveNotSelf, pickAliveByCamp, locale, world) =>
      request.allowedTools.includes("choose_wild_model")
        ? { name: "choose_wild_model", args: { target_id: pickAliveNotSelf()! } }
        : (ORDINARY_WOLF_CONTRIBUTIONS.runtime.baselineAction?.(
            role,
            request,
            pickAliveNotSelf,
            pickAliveByCamp,
            locale,
            world,
          ) ?? null),
  },
  presentation: nativeRolePresentation("wild_child"),
};

/**
 * 负责分别推导狼队知识、聊天参与和刀权。输入为当前 World 角色及明确运行政策；输出保留队友、狼聊、狼刀名单和事件受众。狼阵营本身不等于拥有全部狼队权限，不据历史知识授予当前刀权。
 */
import { scholarMentorPackBlocked } from "./scholar_mentor/night_frame";
import { animalPackKnifeBlocked } from "./animal_dream/authority";
import { nightmareKnifeBlocked } from "./nightmare_shadow/night_frame";
import { weddingMember, ghostBrideReady, weddingSetup } from "./ghost_bride/authority";
import { initialIdentitySetupReady } from "./initial_identity/deal";
import { COMPONENT } from "../../../core/domain/components/names";
import type { RoleComponent } from "../../../core/domain/components/role";
import {
  Camp,
  type EntityId,
  type GameEvent,
  type WolfTeamEventType,
} from "../../../core/domain/model";
import type { World } from "../../../core/domain/world";
import type { RoleCatalog } from "./catalog";
import type { WolfTeamPermissions } from "./contracts";

const NO_ACCESS: WolfTeamPermissions = Object.freeze({
  recognizedByPack: false,
  recognizes: "none",
  canChat: false,
  canVoteForKill: false,
});

/** 只查询角色当前的明确权限；不依赖全局目录，也不写入角色或库存。 */
export function wolfTeamPermissions(
  role: RoleComponent | undefined,
  catalog: RoleCatalog,
  world?: World,
): WolfTeamPermissions {
  if (world && !initialIdentitySetupReady(world)) return NO_ACCESS;
  if (!role || role.camp !== Camp.Wolf) return NO_ACCESS;
  if (world && weddingSetup(world) && (!ghostBrideReady(world) || weddingMember(world, role)))
    return NO_ACCESS;
  const permissions = catalog.runtime(role.role)?.wolfTeam;
  const result =
    typeof permissions === "function" ? permissions(role, world) : (permissions ?? NO_ACCESS);
  return world &&
    (nightmareKnifeBlocked(world) ||
      scholarMentorPackBlocked(world) ||
      animalPackKnifeBlocked(world))
    ? { ...result, canVoteForKill: false }
    : result;
}

export function knownWolfTeammates(
  world: World,
  actorId: EntityId,
  catalog: RoleCatalog,
): EntityId[] {
  const viewer = wolfTeamPermissions(world.getComponent(actorId, COMPONENT.Role), catalog, world);
  if (viewer === NO_ACCESS) return [];
  const role = world.getComponent(actorId, COMPONENT.Role);
  const snapshot = role?.camp === Camp.Wolf && catalog.runtime(role.role)?.knownTeammates;
  if (snapshot)
    return [...new Set(snapshot(role!, world))]
      .filter((id) => id !== actorId && world.getComponent(id, COMPONENT.Role)?.camp === Camp.Wolf)
      .sort((a, b) => a - b);
  if (viewer.recognizes === "none") return [];
  // 身份知识独立于尚未公告的死亡，不能按真实存活状态重写已知队友。
  return world
    .entityIds()
    .filter((id) => {
      if (id === actorId) return false;
      const target = world.getComponent(id, COMPONENT.Role);
      if (target?.camp !== Camp.Wolf) return false;
      if (viewer.recognizes === "all") return true;
      if (viewer.recognizes === "pack")
        return wolfTeamPermissions(target, catalog, world).recognizedByPack;
      return viewer.recognizes.includes(target.role);
    })
    .sort((a, b) => a - b);
}

export function wolfChatParticipants(world: World, catalog: RoleCatalog): EntityId[] {
  return world
    .getAliveEntityIds()
    .filter(
      (id) => wolfTeamPermissions(world.getComponent(id, COMPONENT.Role), catalog, world).canChat,
    )
    .sort((a, b) => a - b);
}

export function wolfKnifeHolders(world: World, catalog: RoleCatalog): EntityId[] {
  return world
    .getAliveEntityIds()
    .filter(
      (id) =>
        wolfTeamPermissions(world.getComponent(id, COMPONENT.Role), catalog, world).canVoteForKill,
    )
    .sort((a, b) => a - b);
}

/** 在事实发布时捕获一次受众；此受众包只用于引擎／Tape，不随后续阵营变化补发历史。 */
export function wolfTeamEvent<K extends WolfTeamEventType>(
  world: World,
  catalog: RoleCatalog,
  event: Omit<Extract<GameEvent, { type: K }>, "audience">,
): Extract<GameEvent, { type: K }> {
  const recipients = wolfChatParticipants(world, catalog);
  if (event.type === "wolf_kill_vote_cast") recipients.push(...wolfKnifeHolders(world, catalog));
  return {
    ...event,
    audience: Object.freeze([...new Set(recipients)].sort((a, b) => a - b)),
  } as Extract<GameEvent, { type: K }>;
}

/**
 * 负责在校验和提交时点查询原生自爆资格。输入为当前角色及 Catalog 的运行贡献；输出为原布尔资格，不写状态、开启自爆窗口或授予请求权限。
 */
import type { RoleComponent } from "../../../core/domain/components/role";
import type { RoleCatalog } from "./catalog";

export function canRoleSelfDestruct(role: RoleComponent, catalog: RoleCatalog): boolean {
  const capability = catalog.runtime(role.role)?.canSelfDestruct;
  return typeof capability === "function" ? capability(role) : capability === true;
}

/**
 * 负责聚合通用、警长和角色运行校验贡献。输入为原上下文与工具调用；输出为首个规则拒绝或 null。
 * 有来源赠枪保留专属校验，普通角色在原时点读取当前规则；不提交动作、付款或执行结算。
 */
import { RuleError, type RuleViolation } from "@ai-werewolf-arena/game-contract";
import { ToolName } from "../../../core/domain/model";
import { COMMON_VALIDATION_RULES } from "../common/validation_rules";
import { RoleCatalog } from "../roles/catalog";
import { getDefaultRoleCatalog } from "../roles/role-catalog-assembly";
import { SHERIFF_VALIDATION_RULES } from "../sheriff/validation_rules";
import { ToolRuleMap, ValidationRuleContext } from "./contracts";
import { validateGiftGun } from "../roles/death_abilities";

function buildDefaultRules(roleProfileRegistry: RoleCatalog): ToolRuleMap {
  const rules: ToolRuleMap = {
    ...COMMON_VALIDATION_RULES,
    ...SHERIFF_VALIDATION_RULES,
  };
  for (const { runtime: profile } of roleProfileRegistry.allRuntime()) {
    if (profile.validationRules) {
      Object.assign(rules, profile.validationRules);
    }
  }
  return rules;
}

/** 工具校验规则注册表。 */
export class ToolValidationRuleRegistry {
  private readonly rules: ToolRuleMap;
  private readonly useProfileRules: boolean;

  constructor(
    rules?: ToolRuleMap,
    private readonly roleProfileRegistry: RoleCatalog = getDefaultRoleCatalog(),
  ) {
    this.rules = { ...(rules ?? buildDefaultRules(roleProfileRegistry)) };
    this.useProfileRules = rules === undefined;
  }

  validate(ctx: Omit<ValidationRuleContext, "roleCatalog">): RuleViolation | null {
    if (this.useProfileRules && ctx.toolCall.name === "shoot" && ctx.abilityId !== undefined)
      return validateGiftGun({ ...ctx, roleCatalog: this.roleProfileRegistry });
    // 同名工具可以归不同角色库存；在原调用点按当前角色读取规则，不能只靠全局索引授权。
    const rule =
      (this.useProfileRules
        ? this.roleProfileRegistry.runtime(ctx.role.role)?.validationRules?.[ctx.toolCall.name]
        : undefined) ?? this.rules[ctx.toolCall.name as ToolName];
    if (!rule) {
      return { code: RuleError.UnknownTool };
    }
    const result = rule({ ...ctx, roleCatalog: this.roleProfileRegistry });
    return !result
      ? null
      : typeof result === "string"
        ? { code: RuleError.CustomRuleError, message: result }
        : result;
  }
}

let defaultRegistry: ToolValidationRuleRegistry | null = null;

/** 获取默认工具校验规则注册表实例。 */
export function getDefaultToolValidationRuleRegistry(): ToolValidationRuleRegistry {
  if (!defaultRegistry) {
    defaultRegistry = new ToolValidationRuleRegistry();
  }
  return defaultRegistry;
}

