    world,
    config,
    configJson,
    actorId: actor.id,
    participants,
    state: state as GhostBrideState,
    status: "pending",
    pair: null,
    group: null,
    votes: [],
    consent: null,
    chats: 0,
    setupCurrent: null,
    turn: null,
    pendingChat: null,
    assignments: null,
    nights: new Map(),
    activeNight: null,
