    binding: b,
    day,
    capture,
    isCurrent,
    actorVersions: new Map(
      actorIds.map((id) => [id, aliveLifeVersion(b.participants.get(id)!.life)!]),
    ),
    targetVersions: new Map([...b.participants].map(([id, p]) => [id, aliveLifeVersion(p.life)!])),
