function request(allowedTools: ActionRequest["allowedTools"]): ActionRequest {
  return {
    actorId: 1,
    phase: Phase.Night,
    allowedTools,
    context: { day: 1, stage: "wolf_vote", visible_events: [], turn_constraints: {} },
  };
}

